import { LimoClient } from '@kamino-finance/limo-sdk';
import { RouteParams } from './types';
import BN from 'bn.js';
import { insertAroundRouterInstruction } from './limoLogs';
import { RouterType } from '../consts';
import { Address, createNoopSigner, Instruction } from '@solana/kit';

export async function getLimoLedgerIxsForRoute(args: {
  params: RouteParams;
  limoClient: LimoClient;
  inputTa: Address;
  outputTa: Address;
  maxInputAmountChange: BN;
  minOutputAmountChange: BN;
}): Promise<{ preIx: Instruction; postIx: Instruction }> {
  const { params, limoClient, inputTa, outputTa, maxInputAmountChange, minOutputAmountChange } = args;
  const limoLedgerIxs = await limoClient.assertUserSwapBalancesIxs({
    user: createNoopSigner(params.executor),
    inputTa,
    outputTa,
    maxInputAmountChange: params.overrideAssertMaxInputAmountChange
      ? params.overrideAssertMaxInputAmountChange
      : maxInputAmountChange,
    minOutputAmountChange: params.overrideAssertMinOutputAmountChange
      ? params.overrideAssertMinOutputAmountChange
      : minOutputAmountChange,
  });

  return { preIx: limoLedgerIxs.beforeSwapIx, postIx: limoLedgerIxs.afterSwapIx };
}

// This will not work for router types that do not have a pre known instruction to wrap around (clover)
export function insertLimoLedgerIxsAroundRouterInstruction(
  instructions: Instruction[],
  routerType: RouterType,
  params: RouteParams,
  preIx: Instruction,
  postIx: Instruction,
): Instruction[] {
  const newInstructions = insertAroundRouterInstruction(instructions, routerType, preIx, postIx, params);

  return newInstructions;
}

export function includeLedgerIxs(params: RouteParams): boolean {
  if (params.assertSwapBalances === undefined) {
    return false;
  }
  return params.assertSwapBalances == true && params.swapType === 'exactIn';
}
